import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    index = int(ctx.index)
    value = float(index)
    return {"inputs": synth.Tensor(torch.tensor([value])), "target_values": synth.Tensor(torch.tensor([value + float(index % 2)])), "environment_ids": index % 2}
class IRMModel(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=1, out_features=1)
    def forward(self, inputs):
        return {"prediction": self.network(inputs)}
dataset = synth.Spec("irm-regression", generator=samples, size=4, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
trainer = Trainer(IRMModel(), train, recipe="structured-objective", recipe_config={"loss": "irm", "loss_kwargs": {"penalty_weight": 0.1}, "bindings": {"logits_or_prediction": {"output": "prediction"}, "targets": {"batch": "target_values"}, "environment_ids": {"batch": "environment_ids"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
